package com.bloxarena.kit;

import com.bloxarena.kit.KitRole;

public enum KitType {
    BLADE("\u30d6\u30ec\u30fc\u30c9", "\u00a76\u2694 \u30d6\u30ec\u30fc\u30c9 \u00a77(Duelist)", "\u6b63\u9762\u306e1v1\u3067\u8ca0\u3051\u306a\u3044\u738b\u9053\u30d5\u30a1\u30a4\u30bf\u30fc", KitRole.DUELIST, "\u541b\u306f\u300c\u5263\u8c6a\u300d\u3060\u3002\u5263\u3092\u632f\u308b\u3044\u3001\u6575\u9663\u3092\u5207\u308a\u88c2\u3051\u3002", "\u4e00\u6483\u96e2\u8131\u304c\u57fa\u672c\u3060\u3002\u8ddd\u96e2\u3092\u8a70\u3081\u3066\u65ac\u3063\u305f\u3089\u5373\u96e2\u308c\u308b\u3002ULT\u30c7\u30a3\u30e1\u30f3\u30b7\u30e7\u30f3\u30d6\u30ec\u30a4\u30af\u306f\u8907\u6570\u4eba\u3092\u4e00\u76f4\u7dda\u306b\u8cab\u3051"),
    BREAKER("\u30d6\u30ec\u30a4\u30ab\u30fc", "\u00a7c\u25b2 \u30d6\u30ec\u30a4\u30ab\u30fc \u00a77(Duelist)", "\u65a7\u30b9\u30ad\u30eb\u3067\u7a81\u9032\u3057\u6575\u9663\u3092\u5d29\u3059\u6a5f\u52d5\u578b", KitRole.DUELIST, "\u541b\u306f\u300c\u7834\u58ca\u8005\u300d\u3060\u3002\u305d\u306e\u7a81\u6483\u3067\u5168\u3066\u3092\u7834\u58ca\u3057\u308d\u3002", "\u6301\u4e45\u6226\u3067\u524a\u308a\u5207\u308b\u306e\u304c\u738b\u9053\u3002\u30bf\u30c3\u30af\u30eb\u306f\u6b63\u9762\u304b\u3089\u3067\u306f\u306a\u304f\u6575\u306e\u80cc\u5f8c\u304b\u3089\u5f53\u3066\u3001\u4f53\u52e2\u3092\u5d29\u3057\u3066\u304b\u3089\u65a7\u3092\u632f\u308c"),
    NINJA("\u30cb\u30f3\u30b8\u30e3", "\u00a72\u25cf \u30cb\u30f3\u30b8\u30e3 \u00a77(Duelist)", "\u900f\u660e\u5316\u30b9\u30ad\u30eb\u3067\u6575\u306e\u80cc\u5f8c\u3092\u53d6\u308b\u5947\u8972\u578b", KitRole.DUELIST, "\u541b\u306f\u300c\u5f71\u6cd5\u5e2b\u300d\u3060\u3002\u6575\u306e\u88cf\u3092\u53d6\u308a\u3001\u652a\u4e71\u305b\u3088\u3002", "\u900f\u660e\u5316\u3067\u95c7\u306b\u7d1b\u308c\u3001\u80cc\u5f8c\u3092\u53d6\u3063\u3066\u4e00\u6483\u3067\u6c7a\u3081\u308b\u3002\u6c7a\u3081\u305f\u3089\u5373\u6d88\u3048\u308d\u3002\u6575\u306b\u8ffd\u308f\u308c\u308b\u7acb\u5834\u306b\u306a\u308b\u306a"),
    BERSERKER("\u30d0\u30fc\u30b5\u30fc\u30ab\u30fc", "\u00a74\u26a1 \u30d0\u30fc\u30b5\u30fc\u30ab\u30fc \u00a77(Duelist)", "\u9023\u7d9a\u7206\u767a\u30b9\u30ad\u30eb\u3067\u5236\u5727\u3059\u308b\u8d85\u653b\u6483\u578b", KitRole.DUELIST, "\u541b\u306f\u300c\u6226\u9b3c\u300d\u3060\u3002\u6012\u308a\u3092\u89e3\u304d\u653e\u3061\u3001\u6575\u3092\u7c89\u7815\u305b\u3088\u3002", "\u524d\u7dda\u306e\u58c1\u3068\u306a\u308c\u3002\u4f4e\u4f53\u529b\u307b\u3069\u65a7\u304c\u5501\u308b\u3001\u7015\u6b7b\u3053\u305d\u672c\u9818\u767a\u63ee\u3002\u9003\u3052\u305a\u306b\u6700\u524d\u7dda\u3067\u66b4\u308c\u308d"),
    SNIPER("\u30b9\u30ca\u30a4\u30d1\u30fc", "\u00a77\u2605 \u30b9\u30ca\u30a4\u30d1\u30fc \u00a77(Duelist)", "\u72d9\u6483\u773c\u3067\u6575\u3092\u30de\u30fc\u30af\u3057\u4e00\u6483\u5fc5\u6bba", KitRole.DUELIST, "\u541b\u306f\u300c\u795e\u5c04\u624b\u300d\u3060\u3002\u72d9\u3044\u6f84\u307e\u3057\u3001\u4e00\u6483\u3067\u4ed5\u7559\u3081\u308d\u3002", "\u7167\u6e96\u3092\u5408\u308f\u305b\u30667\u79d2\u3001\u4e00\u6483\u5fc5\u6bba\u306e\u72d9\u6483\u304c\u6c7a\u307e\u308b\u3002\u5c4b\u6839\u306e\u4e0a\u3092\u5236\u5727\u3057\u3001\u4f4d\u7f6e\u304c\u30d0\u30ec\u305f\u3089\u5373\u30ea\u30ed\u30b1\u30fc\u30c8"),
    COUNTER("\u30ab\u30a6\u30f3\u30bf\u30fc", "\u00a79\u25c6 \u30ab\u30a6\u30f3\u30bf\u30fc \u00a77(Duelist)", "\u30d1\u30ea\u30a3\u3067\u76f8\u624b\u3092\u7121\u529b\u5316\u3059\u308b\u30bf\u30a4\u30df\u30f3\u30b0\u578b", KitRole.DUELIST, "\u541b\u306f\u300c\u65ad\u7f6a\u8005\u300d\u3060\u3002\u6575\u306e\u653b\u6483\u3092\u898b\u5207\u308a\u3001\u305d\u306e\u5203\u3067\u88c1\u3051\u3002", "\u6575\u306e\u653b\u6483\u3092\u3088\u304f\u8aad\u307f\u3001\u30d1\u30ea\u30a3\u3067\u7121\u529b\u5316\u3057\u308d\u3002\u5b88\u308a\u304d\u3063\u305f\u76f4\u5f8c\u306e\u4e00\u6483\u304c\u6700\u5927\u306e\u53cd\u6483\u306b\u306a\u308b"),
    PYRO("\u30d1\u30a4\u30ed", "\u00a76\u25b2 \u30d1\u30a4\u30ed \u00a77(Duelist)", "\u708e\u306e\u5263\u3068\u5f13\uff0b\u696d\u708e\u30b9\u30ad\u30eb\u3067\u713c\u304d\u5c3d\u304f\u3059", KitRole.DUELIST, "\u541b\u306f\u300c\u706b\u846c\u8005\u300d\u3060\u3002\u696d\u706b\u3092\u7e8f\u3044\u3001\u6575\u3092\u7070\u71fc\u3078\u5e30\u305b\u3002", "\u72ed\u6240\u3067\u706b\u3092\u653e\u3066\u3002\u713c\u304b\u308c\u305f\u6575\u306f\u9003\u3052\u5834\u3092\u5931\u3046\u3002\u706b\u306e\u5f13\u306e\u71c3\u713c\u3068\u696d\u706b\u3067\u7bc4\u56f2\u3092\u713c\u304d\u5c3d\u304f\u305b"),
    LANCER("\u30e9\u30f3\u30b5\u30fc", "\u00a7b\u25c6 \u30e9\u30f3\u30b5\u30fc \u00a77(Duelist)", "\u523a\u7a81\u3067\u9577\u3044\u30ea\u30fc\u30c1\u304b\u3089\u6575\u3092\u8cab\u304f\u69cd\u4f7f\u3044", KitRole.DUELIST, "\u541b\u306f\u300c\u69cd\u4f7f\u3044\u300d\u3060\u3002\u9593\u5408\u3044\u3092\u5236\u3057\u3001\u6575\u3092\u8cab\u3051\u3002", "\u5c04\u7a0b10m\u3092\u4fe1\u3058\u308d\u3002\u7a81\u9032\u3067\u9593\u5408\u3044\u3092\u6f70\u3057\u3001ULT\u4e2d\u306f\u6700\u524d\u7dda\u306e\u69cd\u3067\u6575\u306e\u968a\u5217\u3092\u8cab\u3051"),
    JESTER("\u30b8\u30a7\u30b9\u30bf\u30fc", "\u00a7e\u2605 \u30b8\u30a7\u30b9\u30bf\u30fc \u00a77(Duelist)", "\u75be\u8d70\u30b9\u30ad\u30eb\u3068\u30a8\u30f3\u30d1\u3067\u7ffb\u5f04\u3059\u308b\u9ad8\u6a5f\u52d5\u65a7\u4f7f\u3044", KitRole.DUELIST, "\u541b\u306f\u300c\u6b3a\u779e\u8005\u300d\u3060\u3002\u6575\u3092\u6b3a\u304d\u3001\u6226\u5834\u3092\u5632\u7b11\u3048\u3002", "\u75be\u8d70\u3068\u30a8\u30f3\u30d1\u3067\u6575\u3092\u7ffb\u5f04\u3057\u308d\u3002\u6311\u767a\u3057\u3066\u72d9\u308f\u305b\u3001\u4e71\u6226\u306e\u4e2d\u5fc3\u3067\u65a7\u3092\u56de\u3059\u3002\u76ae\u8089\u306f\u6700\u5927\u306e\u6b66\u5668\u3060"),
    VAMPIRE("\u30f4\u30a1\u30f3\u30d1\u30a4\u30a2", "\u00a74\u2764 \u30f4\u30a1\u30f3\u30d1\u30a4\u30a2 \u00a77(Duelist)", "\u5438\u8840\u30b2\u30fc\u30b8\u3092\u6e9c\u3081\u3066\u6bb5\u968e\u5f37\u5316\u3059\u308b\u5909\u8eab\u5f62", KitRole.DUELIST, "\u541b\u306f\u300c\u5438\u8840\u9a0e\u300d\u3060\u3002\u8840\u306e\u529b\u3092\u89e3\u304d\u653e\u3061\u3001\u6575\u3092\u7d76\u671b\u3078\u6c88\u3081\u3088\u3002", "\u5438\u8840\u3067\u56de\u5fa9\u3057\u306a\u304c\u3089\u524d\u7dda\u306b\u7acb\u3061\u7d9a\u3051\u308d\u3002\u30b2\u30fc\u30b8\u3092\u6e9c\u3081\u3066\u6bb5\u968e\u5f37\u5316\u3002\u663c\u306f\u5f31\u3044\u3001\u591c\u306b\u3053\u305d\u7259\u3092\u5265\u3051"),
    BOMBER("\u30dc\u30de\u30fc", "\u00a7c\u25cf \u30dc\u30de\u30fc \u00a77(Duelist)", "\u5730\u96f7\u3092\u8a2d\u7f6e\u3057\u4efb\u610f\u8d77\u7206\u3059\u308b\u30c8\u30e9\u30c3\u30d7\u578b", KitRole.DUELIST, "\u541b\u306f\u300c\u7206\u8f5f\u300d\u3060\u3002\u7206\u708e\u3092\u64cd\u308a\u3001\u6575\u3092\u5439\u304d\u98db\u3070\u305b\u3002", "\u7206\u5f3e\u306f\u8aad\u308f\u305b\u3066\u304b\u3089\u7f6e\u304f\u3002\u9003\u3052\u9053\u306b\u5730\u96f7\u3092\u5fcd\u3070\u305b\u3066\u8d77\u7206\u3002\u81ea\u7206\u306b\u6ce8\u610f\u3001\u8ddd\u96e2\u306f\u5e38\u306b\u78ba\u4fdd\u3057\u308d"),
    COOK("\u6599\u7406\u4eba", "\u00a76\u25c6 \u6599\u7406\u4eba \u00a77(Duelist)", "\u30e9\u30f3\u30c0\u30e0\u98df\u6750\u304b\u3089\u6599\u7406\u3092\u4f5c\u308a\u30d0\u30d5/\u30c7\u30d0\u30d5\u3092\u6492\u304f", KitRole.DUELIST, "\u541b\u306f\u300c\u7f8e\u98df\u5bb6\u300d\u3060\u3002\u81f3\u9ad8\u306e\u6599\u7406\u3067\u3001\u4ef2\u9593\u3092\u52dd\u5229\u3078\u5c0e\u3051\u3002", "\u5473\u65b9\u306b\u6599\u7406\u3092\u914d\u308a\u3001\u30d0\u30d5\u3092\u6492\u304f\u306e\u304c\u4ed5\u4e8b\u3002\u524d\u7dda\u306f\u5f35\u3089\u306a\u3044\u3002\u30c7\u30d0\u30d5\u306f\u6575\u306e\u56de\u5fa9\u5f79\u3078\u5c4a\u3051\u308d"),
    GRANG("\u30b0\u30e9\u30f3\u30b0", "\u00a77\u25b2 \u30b0\u30e9\u30f3\u30b0 \u00a77(Duelist)", "\u76fe\u30c1\u30e3\u30fc\u30b8\u3067\u7a81\u6483\u3059\u308b\u6a5f\u52d5\u8981\u585e", KitRole.DUELIST, "\u541b\u306f\u300c\u92fc\u9a0e\u300d\u3060\u3002\u92fc\u9244\u306e\u610f\u5fd7\u3067\u3001\u6575\u9663\u3092\u7a81\u7834\u305b\u3088\u3002", "\u76fe\u3092\u30c1\u30e3\u30fc\u30b8\u3057\u3066\u7a81\u6483\u3059\u308b\u6a5f\u52d5\u8981\u585e\u3002ULT\u4e2d\u306f\u52d5\u3051\u308b\u8981\u585e\u3068\u5316\u3057\u3001\u5473\u65b9\u306e\u76fe\u3092\u52d9\u3081\u308d"),
    SCOUT("\u30b9\u30ab\u30a6\u30c8", "\u00a7a\u2605 \u30b9\u30ab\u30a6\u30c8 \u00a77(Initiator)", "\u30ea\u30b3\u30f3\u30dc\u30eb\u30c8\u3067\u6575\u4f4d\u7f6e\u3092\u53ef\u8996\u5316\u3059\u308b\u5075\u5bdf\u5f79", KitRole.INITIATOR, "\u541b\u306f\u300c\u5343\u91cc\u773c\u300d\u3060\u3002\u6575\u3092\u66b4\u304d\u3001\u5473\u65b9\u3078\u52dd\u6a5f\u3092\u3082\u305f\u3089\u305b\u3002", "\u9ad8\u6240\u304b\u3089\u4e00\u65b9\u7684\u306b\u6483\u3061\u3001\u898b\u3064\u304b\u3063\u305f\u3089\u5373\u30ea\u30ed\u30b1\u30fc\u30c8\u3002\u30ea\u30b3\u30f3\u30dc\u30eb\u30c8\u3067\u6575\u4f4d\u7f6e\u3092\u5473\u65b9\u306b\u5171\u6709\u3057\u308d"),
    FLASHER("\u30d5\u30e9\u30c3\u30b7\u30e3\u30fc", "\u00a7b\u26a1 \u30d5\u30e9\u30c3\u30b7\u30e3\u30fc \u00a77(Initiator)", "\u30d5\u30e9\u30c3\u30b7\u30e5\u30d0\u30f3\u7403\u3067\u6575\u3092\u76f2\u76ee\u5316\u3057\u7a81\u7834\u53e3\u3092\u4f5c\u308b", KitRole.INITIATOR, "\u541b\u306f\u300c\u9583\u5149\u300d\u3060\u3002\u5149\u3067\u6575\u306e\u8996\u754c\u3092\u596a\u3048\u3002", "\u7a81\u5165\u306e\u5408\u56f3\u306b\u95c3\u5149\u3060\u3002\u58c1\u8d8a\u3057\u306b\u711a\u3044\u3066\u6575\u3092\u76f2\u76ee\u5316\u3002\u5473\u65b9\u306e\u76ee\u306e\u524d\u3067\u711a\u304b\u306a\u3044\u3001\u5411\u304d\u3060\u3051\u306f\u78ba\u304b\u3081\u308d"),
    MARKSMAN("\u30de\u30fc\u30af\u30b9\u30de\u30f3", "\u00a7c\u25c6 \u30de\u30fc\u30af\u30b9\u30de\u30f3 \u00a77(Initiator)", "\u30d8\u30f4\u30a3\u30fc\u30dc\u30eb\u30c8\u3067\u6575\u306eHP\u4e0a\u9650\u3092\u524a\u308b", KitRole.INITIATOR, "\u541b\u306f\u300c\u9b54\u5f3e\u306e\u5c04\u624b\u300d\u3060\u3002\u9b54\u5f3e\u3092\u653e\u3061\u3001\u6575\u306e\u547d\u3092\u6483\u3061\u629c\u3051\u3002", "\u5473\u65b9\u306e\u30de\u30fc\u30af\u306b\u96c6\u4e2d\u7832\u706b\u3057\u3001\u6575\u306eHP\u4e0a\u9650\u3092\u524a\u308c\u3002\u5f3e\u5207\u308c\u306b\u6ce8\u610f\u3001\u6483\u3064\u77ac\u9593\u3060\u3051\u524d\u306b\u51fa\u308d"),
    SUNDANCE("\u30b5\u30f3\u30c0\u30f3\u30b9", "\u00a7b\u26a1 \u30b5\u30f3\u30c0\u30f3\u30b9 \u00a77(Initiator)", "\u30ea\u30dc\u30eb\u30d3\u30f3\u30b0\u30af\u30ed\u30b9\u30dc\u30a6\u3067\u5f3e\u5e55\u3092\u5f35\u308b", KitRole.INITIATOR, "\u541b\u306f\u300c\u8352\u91ce\u306e\u6c7a\u95d8\u8005\u300d\u3060\u3002\u4e00\u77ac\u306e\u9699\u304c\u3001\u52dd\u6557\u3092\u6c7a\u3081\u308b\u3002", "ULT\u4e2d\u306f12\u767a\u306e\u5f3e\u5e55\u3067\u5236\u5727\u5c04\u6483\u3060\u3002\u4e00\u77ac\u306e\u9699\u304c\u52dd\u6557\u3092\u5206\u3051\u308b\u3002\u30ea\u30ed\u30fc\u30c9\u3092\u5fd8\u308c\u308b\u306a"),
    SWAPPER("\u30b9\u30ef\u30c3\u30d1\u30fc", "\u00a75\u25c6 \u30b9\u30ef\u30c3\u30d1\u30fc \u00a77(Initiator)", "\u76f8\u624b\u3068\u306e\u4f4d\u7f6e\u3092\u5373\u5ea7\u306b\u5165\u308c\u66ff\u3048\u308b\u64b9\u4e71\u578b", KitRole.INITIATOR, "\u541b\u306f\u300c\u8ee2\u63db\u8005\u300d\u3060\u3002\u6575\u306e\u4f4d\u7f6e\u3092\u5165\u308c\u66ff\u3048\u3001\u6226\u6cc1\u3092\u8986\u305b\u3002", "\u6575\u306e\u4f4d\u7f6e\u3092\u5165\u308c\u66ff\u3048\u3066\u5b64\u7acb\u3055\u305b\u308d\u3002\u9ad8\u6240\u306e\u30b9\u30ca\u30a4\u30d1\u30fc\u3068\u5165\u308c\u66ff\u3048\u308c\u3070\u3001\u4e00\u6483\u3067\u846c\u308c\u308b"),
    STICKER("\u30b9\u30c6\u30c3\u30ab\u30fc", "\u00a73\u25cf \u30b9\u30c6\u30c3\u30ab\u30fc \u00a77(Initiator)", "\u30b0\u30e9\u30c3\u30d7\u30eb\u3067\u6575\u3092\u5f15\u304d\u5bc4\u305b\u308b\u6355\u7372\u578b", KitRole.INITIATOR, "\u541b\u306f\u300c\u4e07\u6709\u306e\u624b\u300d\u3060\u3002\u6575\u3092\u5f15\u304d\u5bc4\u305b\u3001\u9003\u3052\u5834\u3092\u596a\u3048\u3002", "\u7c98\u7740\u3067\u6575\u3092\u7e1b\u308a\u3001\u30ad\u30eb\u306f\u5473\u65b9\u306b\u8a17\u305b\u3002\u30b0\u30e9\u30c3\u30d7\u30eb\u3067\u5f15\u304d\u5bc4\u305b\u3001\u9003\u3052\u5834\u3054\u3068\u593a\u3048"),
    DECOY("\u30c7\u30b3\u30a4", "\u00a78\u25c6 \u30c7\u30b3\u30a4 \u00a77(Initiator)", "\u81ea\u8eab\u306e\u5206\u8eab\u3092\u751f\u6210\u3057\u900f\u660e\u5316\u3059\u308b\u6b3a\u779e\u578b", KitRole.INITIATOR, "\u541b\u306f\u300c\u652a\u4e71\u8005\u300d\u3060\u3002\u6575\u3092\u60d1\u308f\u305b\u3001\u6226\u5834\u3092\u652f\u914d\u305b\u3088\u3002", "\u30c7\u30b3\u30a4\u3067\u6575\u306e\u30b9\u30ad\u3092\u8a98\u3048\u3002\u672c\u547d\u306f\u5f71\u304b\u3089\u3060\u3002\u900f\u660e\u5316\u3057\u3066\u59ff\u3092\u6d88\u3057\u3001\u6483\u4e71\u306e\u4e3b\u5c0e\u6a29\u3092\u63e1\u308c"),
    WHIRLWIND("\u30ef\u30fc\u30eb\u30a6\u30a3\u30f3\u30c9", "\u00a7f\u25cf \u30ef\u30fc\u30eb\u30a6\u30a3\u30f3\u30c9 \u00a77(Initiator)", "\u6c17\u6d41\u3067\u6575\u3092\u62bc\u3057\u51fa\u3057\uff0b\u8ffd\u5c3e\u7403\u3067\u6253\u3061\u4e0a\u3052\u308b\u98a8\u4f7f\u3044", KitRole.INITIATOR, "\u541b\u306f\u300c\u65cb\u98a8\u300d\u3060\u3002\u98a8\u3092\u7e8f\u3044\u3001\u6575\u3092\u7a7a\u3078\u821e\u3044\u4e0a\u3052\u308d\u3002", "\u6c17\u6d41\u3067\u6575\u306e\u968a\u5217\u3092\u5d29\u305b\u3002\u6291\u3057\u51fa\u3057\u3066\u5206\u65ad\u3057\u3001\u8ffd\u5c3e\u7403\u3067\u6253\u3061\u4e0a\u3052\u308b\u3002\u4e71\u6226\u3067\u3053\u305d\u8f1d\u304f"),
    NILGIRITAR("\u30cb\u30eb\u30ae\u30ea\u30bf\u30fc\u30eb", "\u00a7f\u25c6 \u30cb\u30eb\u30ae\u30ea\u30bf\u30fc\u30eb \u00a77(Initiator)", "\u30af\u30ed\u30b9\u30dc\u30a6\uff0b\u8fd1\u63a5\u3067\u76fe\u8cab\u901a\u30c0\u30e1\u30fc\u30b8\u3092\u4e0e\u3048\u308b\u98a8\u7a74\u4f7f\u3044", KitRole.INITIATOR, "\u541b\u306f\u300c\u98a8\u7a74\u3092\u958b\u3051\u308b\u8005\u300d\u3060\u3002\u9632\u5fa1\u3092\u8cab\u304d\u3001\u6575\u3092\u7a7f\u3066\u3002", "\u30af\u30ed\u30b9\u30dc\u30a6\u3067\u76fe\u3092\u8cab\u901a\u3057\u3001\u8fd1\u63a5\u3067\u7a81\u304d\u629c\u3051\u308d\u3002\u98a8\u7a74\u306e\u9023\u6483\u306f\u5358\u4f53\u96c6\u4e2d\u3001\u30ad\u30eb\u53d6\u308a\u306b\u56de\u305b"),
    MISTRAL("\u30df\u30b9\u30c8\u30e9\u30eb", "\u00a7f\u25cf \u30df\u30b9\u30c8\u30e9\u30eb \u00a77(Initiator)", "\u70c8\u98a8\u7832\u3067\u6575\u3092\u72ed\u304f\u78ba\u5b9f\u306b\u5439\u304d\u98db\u3070\u3059\u66b4\u98a8\u4f7f\u3044", KitRole.INITIATOR, "\u541b\u306f\u300c\u66b4\u98a8\u300d\u3060\u3002", "\u70c8\u98a8\u5f3e\u306f\u78ba\u5b9f\u306b\u5f53\u3066\u308d\u3002\u7fbd\u3067\u98db\u3093\u3067\u9ad8\u6240\u5236\u5727\u3001\u7740\u5730\u304c\u547d\u7db1\u3002\u964d\u308a\u308b\u5834\u6240\u3092\u5148\u306b\u9078\u3079"),
    ROCKETER("\u30ed\u30b1\u30c3\u30c6\u30a3\u30a2", "\u00a7e\u25b2 \u30ed\u30b1\u30c3\u30c6\u30a3\u30a2 \u00a77(Controller)", "\u30e1\u30ac\u30ed\u30b1\u30c3\u30c8\u3067\u5927\u7206\u767a\u3092\u8d77\u3053\u3059\u30a8\u30ea\u30a2\u5236\u5727\u5f79", KitRole.CONTROLLER, "\u541b\u306f\u300c\u7832\u6483\u624b\u300d\u3060\u3002\u7206\u8f5f\u3092\u97ff\u304b\u305b\u3001\u6575\u9663\u3092\u58ca\u6ec5\u3055\u305b\u3088\u3002", "\u9060\u8ddd\u96e2\u304b\u3089\u306e\u7206\u6483\u304c\u547d\u3060\u3002\u8fd1\u8ddd\u96e2\u3067\u6483\u3064\u306a\u3001\u81ea\u7206\u3059\u308b\u3002\u906e\u853d\u8d8a\u3057\u306b\u6575\u306e\u56fa\u307e\u308a\u3092\u7206\u6483\u3057\u308d"),
    ALCHEMIST("\u30a2\u30eb\u30b1\u30df\u30b9\u30c8", "\u00a7d\u25c6 \u30a2\u30eb\u30b1\u30df\u30b9\u30c8 \u00a77(Controller)", "\u518d\u8abf\u5408\u3067\u30dd\u30fc\u30b7\u30e7\u30f3\u3092\u88dc\u5145\u3057\u7a7a\u9593\u3054\u3068\u652f\u914d", KitRole.CONTROLLER, "\u541b\u306f\u300c\u932c\u91d1\u8853\u5e2b\u300d\u3060\u3002\u79d8\u85ac\u3092\u64cd\u308a\u3001\u6226\u5c40\u3092\u638c\u63e1\u305b\u3088\u3002", "\u5473\u65b9\u306e\u5f8c\u308d\u304b\u3089\u652f\u63f4\u3057\u308d\u3002\u518d\u8abf\u5408\u3067\u5f3e\u85ac\u3092\u88dc\u5145\u3057\u7a7a\u9593\u3054\u3068\u652f\u914d\u3002\u6bd2\u306f\u56de\u5fa9\u5f79\u304b\u3089\u5148\u306b\u843d\u3068\u305b"),
    ENGINEER("\u30a8\u30f3\u30b8\u30cb\u30a2", "\u00a76\u2699 \u30a8\u30f3\u30b8\u30cb\u30a2 \u00a77(Controller)", "\u30ec\u30fc\u30b6\u30fc\u30bf\u30ec\u30c3\u30c8\u3092\u8a2d\u7f6e\u3059\u308b\u5236\u5727\u578b", KitRole.CONTROLLER, "\u541b\u306f\u300c\u6a5f\u69cb\u5e2b\u300d\u3060\u3002\u6a5f\u68b0\u3092\u5f93\u3048\u3001\u6226\u5834\u305d\u306e\u3082\u306e\u3092\u652f\u914d\u305b\u3088\u3002", "\u30bf\u30ec\u30c3\u30c8\u306f\u9ad8\u4f4e\u5dee\u306e\u3042\u308b\u8996\u754c\u306e\u826f\u3044\u5834\u6240\u3078\u3002\u524d\u9762\u306b\u7acb\u305f\u305a\u3001\u6a5f\u68b0\u306e\u5c04\u7dda\u306e\u5f8c\u308d\u304b\u3089\u5236\u5727\u305b\u3088"),
    RESTRICTIONER("\u30ea\u30b9\u30c8\u30ea\u30af\u30b7\u30e7\u30ca\u30fc", "\u00a78\u25cf \u30ea\u30b9\u30c8\u30ea\u30af\u30b7\u30e7\u30ca\u30fc \u00a77(Controller)", "\u81ea\u8eab\u3054\u3068\u5bfe\u8c61\u3092\u62d8\u675f\u3059\u308b\u30ed\u30c3\u30af\u578b", KitRole.CONTROLLER, "\u541b\u306f\u300c\u62d8\u675f\u8005\u300d\u3060\u3002\u6575\u3092\u7e1b\u308a\u4e0a\u3052\u3001\u52dd\u6a5f\u3092\u5275\u308a\u51fa\u305b\u3002", "\u62d8\u675f\u306f\u6700\u512a\u5148\u30bf\u30fc\u30b2\u30c3\u30c8\u306b\u3002\u81ea\u5206\u3054\u3068\u6575\u3092\u7e1b\u308a\u3001\u5f8c\u9000\u3057\u3064\u3064\u5473\u65b9\u306b\u6258\u3059\u3002\u6c7a\u6b7b\u306e\u62d8\u675f\u3053\u305d\u4fa1\u5024\u3060"),
    TRANSPORTER("\u30c8\u30e9\u30f3\u30b9\u30dd\u30fc\u30bf\u30fc", "\u00a73\u25c6 \u30c8\u30e9\u30f3\u30b9\u30dd\u30fc\u30bf\u30fc \u00a77(Controller)", "\u53cc\u65b9\u5411\u30dd\u30fc\u30bf\u30eb\u3092\u8a2d\u7f6e\u3059\u308b\u79fb\u52d5\u578b", KitRole.CONTROLLER, "\u541b\u306f\u300c\u5883\u754c\u6e21\u308a\u300d\u3060\u3002\u7a7a\u9593\u3092\u7e4b\u304e\u3001\u65b0\u305f\u306a\u6226\u5834\u3092\u5207\u308a\u62d3\u3051\u3002", "\u30dd\u30fc\u30bf\u30eb\u3067\u5473\u65b9\u306e\u5947\u8972\u8def\u3092\u4f5c\u308c\u3002\u6575\u306e\u88cf\u3092\u7a81\u304f\u51fa\u53e3\u3068\u3001\u6483\u9000\u306e\u5165\u53e3\u3092\u540c\u6642\u306b\u7bc9\u3051"),
    KREUTZ("\u30af\u30ed\u30a4\u30c4", "\u00a75\u2605 \u30af\u30ed\u30a4\u30c4 \u00a77(Controller)", "\u9b54\u6cd5\u30ab\u30fc\u30c9\u3092\u5f15\u304d\u69d8\u3005\u306a\u52b9\u679c\u3092\u767a\u52d5\u3059\u308b\u9b54\u8853\u5e2b", KitRole.CONTROLLER, "\u541b\u306f\u300c\u9b54\u6cd5\u4f7f\u3044\u300d\u3060\u3002\u904b\u547d\u306e\u30ab\u30fc\u30c9\u3092\u5f15\u304d\u3001\u6226\u5834\u3092\u638c\u63e1\u305b\u3088\u3002", "\u30de\u30ca\u7ba1\u7406\u304c\u547d\u3060\u3002\u30ab\u30fc\u30c9\u3067\u5c0f\u3055\u306a\u6709\u5229\u3092\u7a4d\u307f\u91cd\u306d\u3001\u30d5\u30eb\u30aa\u30fc\u30c0\u30fc\u306f\u96c6\u56e3\u6226\u306e\u6c7a\u6226\u5834\u3067\u5207\u308c"),
    NECRO("\u30cd\u30af\u30ed", "\u00a78\u2620 \u30cd\u30af\u30ed \u00a77(Controller)", "\u30b9\u30b1\u30eb\u30c8\u30f33\u90e8\u968a\u3092\u53ec\u559a\u30fb\u6307\u63ee\u3059\u308b\u5c4d\u4f53\u821e\u8e0f\u8005", KitRole.CONTROLLER, "\u541b\u306f\u300c\u6b7b\u4f53\u821e\u8e0f\u8005\u300d\u3060\u3002\u6b7b\u8005\u3092\u5f93\u3048\u3001\u6b7b\u306e\u821e\u8e0f\u4f1a\u3092\u59cb\u3081\u3088\u3002", "\u5175\u968a\u3092\u7fa4\u308c\u3067\u904b\u7528\u3057\u308d\u3002\u81ea\u5206\u306f\u5f8c\u308d\u304b\u3089\u6307\u63ee\u3057\u3001\u6b7b\u4f53\u306e\u7fa4\u308c\u3067\u6575\u9663\u3092\u5305\u56f2\u3059\u308b"),
    TRAPPER("\u30c8\u30e9\u30c3\u30d1\u30fc", "\u00a73\u25b2 \u30c8\u30e9\u30c3\u30d1\u30fc \u00a77(Sentinel)", "\u4e0d\u53ef\u8996\u306e\u7f60\u3067\u6575\u3092\u884c\u52d5\u4e0d\u80fd\u306b\u3059\u308b\u9632\u885b\u578b", KitRole.SENTINEL, "\u541b\u306f\u300c\u7f60\u5e2b\u300d\u3060\u3002\u7f60\u3092\u5de1\u3089\u305b\u3001\u6575\u3092\u72e9\u308a\u5c3d\u304f\u305b\u3002", "\u5473\u65b9\u3092\u56f2\u3080\u58c1\u306e\u5185\u5074\u306b\u7f60\u3092\u4ed5\u639b\u3051\u308d\u3002\u4e0d\u53ef\u8996\u306e\u7f60\u3067\u901a\u8def\u3092\u5c01\u3058\u3001\u6575\u3092\u72e9\u308a\u5c3d\u304f\u305b"),
    GUARDIAN("\u30ac\u30fc\u30c7\u30a3\u30a2\u30f3", "\u00a7f\u25c6 \u30ac\u30fc\u30c7\u30a3\u30a2\u30f3 \u00a77(Sentinel)", "\u9244\u58c1\u30b9\u30ad\u30eb\u3067\u4e00\u5b9a\u6642\u9593\u7121\u6575\u5316\u3059\u308b\u76fe\u5f79", KitRole.SENTINEL, "\u541b\u306f\u300c\u4e0d\u6c88\u8266\u300d\u3060\u3002\u3044\u304b\u306a\u308b\u731b\u653b\u306b\u3082\u6c88\u307e\u305a\u3001\u6226\u7dda\u3092\u652f\u3048\u7d9a\u3051\u308d\u3002", "\u5473\u65b9\u306e\u524d\u306b\u7acb\u3061\u585e\u304c\u308c\u3002\u7121\u6575\u5316\u306f\u7015\u6b7b\u306e\u5473\u65b9\u3092\u5e87\u3046\u6642\u306b\u3002\u9244\u58c1\u306e\u5f8c\u308d\u304c\u5473\u65b9\u306e\u751f\u547d\u7dda\u3060"),
    MEDIC("\u30e1\u30c7\u30a3\u30c3\u30af", "\u00a75\u2764 \u30e1\u30c7\u30a3\u30c3\u30af \u00a77(Sentinel)", "\u30d5\u30a3\u30fc\u30eb\u30c9\u30b1\u30a2\u3067\u5473\u65b9\u3092\u7bc4\u56f2\u56de\u5fa9\u3059\u308b\u652f\u63f4\u578b", KitRole.SENTINEL, "\u541b\u306f\u300c\u751f\u547d\u7dda\u300d\u3060\u3002\u4ef2\u9593\u3092\u6551\u3044\u3001\u6226\u7dda\u3092\u7e4b\u304e\u6b62\u3081\u3088\u3002", "\u6700\u5f8c\u5c3e\u304b\u3089\u6cbb\u7642\u3092\u7d9a\u3051\u308d\u3002\u81ea\u5206\u304c\u843d\u3061\u305f\u3089\u5168\u6ec5\u3059\u308b\u3002\u30d5\u30a3\u30fc\u30eb\u30c9\u30b1\u30a2\u306e\u4f4d\u7f6e\u53d6\u308a\u304c\u5168\u3066\u3060"),
    SUPPORTER("\u30b5\u30dd\u30fc\u30bf\u30fc", "\u00a7a\u25cf \u30b5\u30dd\u30fc\u30bf\u30fc \u00a77(Sentinel)", "\u518d\u8abf\u9054\u3067\u30d0\u30d5\u30dd\u30fc\u30b7\u30e7\u30f3\u3092\u88dc\u5145\u3057\u6226\u5834\u3092\u652f\u3048\u308b", KitRole.SENTINEL, "\u541b\u306f\u300c\u52a0\u8b77\u8005\u300d\u3060\u3002\u4ef2\u9593\u3078\u529b\u3092\u6388\u3051\u3001\u52dd\u5229\u3078\u5c0e\u3051\u3002", "\u5473\u65b9\u306e\u5f37\u5316\u3092\u6700\u512a\u5148\u3057\u308d\u3002\u81ea\u5206\u306f\u6226\u308f\u306a\u3044\u3002\u30d0\u30d5\u3092\u914d\u308b\u5148\u304c\u52dd\u6557\u3092\u6c7a\u3081\u308b"),
    PHANTOM("\u30d5\u30a1\u30f3\u30c8\u30e0", "\u00a77\u25c6 \u30d5\u30a1\u30f3\u30c8\u30e0 \u00a77(Sentinel)", "\u970a\u4f53\u5316\u3067\u900f\u660e\uff0b\u7121\u6575\u306b\u306a\u308b\u56de\u907f\u578b", KitRole.SENTINEL, "\u541b\u306f\u300c\u5e7b\u5f71\u300d\u3060\u3002\u59ff\u3092\u6666\u307e\u3057\u3001\u6575\u3092\u7ffb\u5f04\u305b\u3088\u3002", "\u7121\u6575\u306e\u970a\u4f53\u3067\u6575\u9663\u3092\u652a\u4e71\u3057\u308d\u3002\u89e3\u9664\u524d\u306b\u96e2\u8131\u3001\u30bf\u30a4\u30de\u30fc\u3060\u3051\u306f\u6570\u3048\u3066\u304a\u3051"),
    ANCHOR("\u30a2\u30f3\u30ab\u30fc", "\u00a79\u25b2 \u30a2\u30f3\u30ab\u30fc \u00a77(Sentinel)", "\u78c1\u5834\u3067\u5468\u56f2\u306e\u6575\u3092\u6e1b\u901f\u3055\u305b\u308b\u5236\u5727\u578b", KitRole.SENTINEL, "\u541b\u306f\u300c\u505c\u6ede\u8005\u300d\u3060\u3002\u9818\u57df\u3092\u5c55\u958b\u3057\u3001\u6575\u306e\u9032\u8ecd\u3092\u5c01\u3058\u3088\u3002", "\u5473\u65b9\u306e\u9328\u3068\u3057\u3066\u524d\u7dda\u306b\u7acb\u3061\u7d9a\u3051\u308d\u3002\u78c1\u5834\u3067\u6575\u306e\u9032\u8ecd\u3092\u6e1b\u901f\u3055\u305b\u3001\u9003\u3052\u5834\u3082\u593a\u3048"),
    RELEASER("\u30ea\u30ea\u30fc\u30b5\u30fc", "\u00a7e\u26a1 \u30ea\u30ea\u30fc\u30b5\u30fc \u00a77(Sentinel)", "\u30d0\u30fc\u30b9\u30c8\u7cfb\u30b9\u30ad\u30eb\u7279\u5316\u3002\u5927\u7206\u767a\uff0b\u5c0f\u7206\u767a\u3092\u99c6\u4f7f", KitRole.SENTINEL, "\u541b\u306f\u300c\u89e3\u653e\u8005\u300d\u3060\u3002\u79d8\u3081\u305f\u308b\u529b\u3092\u89e3\u304d\u653e\u3061\u3001\u5168\u3066\u3092\u5439\u304d\u98db\u3070\u305b\u3002", "\u8caf\u3081\u305f\u529b\u306f\u96c6\u56e3\u6226\u306e\u8981\u3067\u89e3\u653e\u3057\u308d\u3002\u5c0f\u7206\u767a\u3067\u524a\u308a\u3001\u6e9c\u3081\u305f\u5927\u7206\u767a\u3067\u4e00\u7db2\u6253\u5c3d\u306b\u305b\u3088"),
    BULWARK("\u30d6\u30eb\u30ef\u30fc\u30af", "\u00a7f\u25b2 \u30d6\u30eb\u30ef\u30fc\u30af \u00a77(Sentinel)", "\u30a6\u30a9\u30fc\u30eb\u5c55\u958b\u3067\u5473\u65b9\u3092\u5b88\u308b\u8981\u585e\u578b", KitRole.SENTINEL, "\u541b\u306f\u300c\u9632\u58c1\u300d\u3060\u3002\u63fa\u308b\u304c\u306c\u76fe\u3067\u3001\u6226\u7dda\u3092\u5b88\u308a\u629c\u3051\u3002", "3\u65b9\u5411\u306e\u58c1\u3067\u6226\u5834\u3092\u533a\u5207\u308c\u3002\u5473\u65b9\u3092\u80cc\u306b\u5b88\u308a\u3001\u5b88\u52e2\u306e\u8981\u3068\u3057\u3066\u5d29\u308c\u308b\u306a"),
    TIMEKEEPER("\u30bf\u30a4\u30e0\u30ad\u30fc\u30d1\u30fc", "\u00a7b\u25cf \u30bf\u30a4\u30e0\u30ad\u30fc\u30d1\u30fc \u00a77(Controller)", "\u6642\u9593\u3092\u64cd\u308a\u30ea\u30ef\u30a4\u30f3\u30c9\u3067\u614b\u52e2\u3092\u7acb\u3066\u76f4\u3059\u652f\u914d\u578b", KitRole.CONTROLLER, "\u541b\u306f\u300c\u6642\u9593\u306e\u4e3b\u300d\u3060\u3002\u6642\u3092\u5dfb\u304d\u623b\u3057\u3001\u6226\u5c40\u3092\u638c\u63e1\u305b\u3088\u3002", "\u6642\u9593\u505c\u6b62\u306f\u6575\u306eULT\u306b\u5408\u308f\u305b\u3066\u4f7f\u3048\u3002\u30ea\u30ef\u30a4\u30f3\u30c9\u3067\u614b\u52e2\u3092\u7acb\u3066\u76f4\u3057\u3001\u53d6\u308a\u623b\u3057\u305f\u6642\u9593\u3067\u52dd\u3066"),
    AEGIS("\u30a4\u30fc\u30b8\u30b9", "\u00a7a\u2605 \u30a4\u30fc\u30b8\u30b9 \u00a77(Sentinel)", "\u5473\u65b9\u3068\u7d46\u3092\u7d50\u3073\u5171\u306b\u5b88\u308b\u5b88\u8b77\u578b", KitRole.SENTINEL, "\u541b\u306f\u300c\u795e\u76fe\u300d\u3060\u3002\u7d46\u3067\u7d50\u3070\u308c\u305f\u8005\u3092\u3001\u6c7a\u3057\u3066\u898b\u6368\u3066\u306a\u3044\u3002", "\u76fe\u3067\u5473\u65b9\u3092\u5b88\u308a\u5207\u308c\u3002\u7d46\u3067\u7d50\u3093\u3060\u8005\u306f\u6c7a\u3057\u3066\u898b\u6368\u3066\u306a\u3044\u3002\u53cd\u6483\u306f\u305d\u306e\u76fe\u306e\u5f8c\u308d\u304b\u3089\u3060"),
    HEXER("\u30d8\u30af\u30b5\u30fc", "\u00a75\u25cf \u30d8\u30af\u30b5\u30fc \u00a77(Controller)", "\u546a\u7e1b\u9818\u57df\u3067\u6575\u306e\u52d5\u304d\u3092\u5c01\u3058\u308b\u9818\u57df\u652f\u914d\u578b", KitRole.CONTROLLER, "\u541b\u306f\u300c\u546a\u8a5b\u8005\u300d\u3060\u3002\u9818\u57df\u3092\u546a\u3044\u3001\u6575\u3092\u7e1b\u308a\u4e0a\u3052\u3088\u3002", "\u546a\u3044\u3067\u6575\u306e\u56de\u5fa9\u3092\u5c01\u3058\u308d\u3002\u546a\u7e1b\u9818\u57df\u306b\u5f15\u304d\u8fbc\u3093\u3060\u7372\u7269\u306f\u3001\u52d5\u3051\u306a\u3044\u307e\u307e\u72e9\u3089\u308c\u308b"),
    REFLECTOR("\u30ea\u30d5\u30ec\u30af\u30bf\u30fc", "\u00a7f\u25c6 \u30ea\u30d5\u30ec\u30af\u30bf\u30fc \u00a77(Sentinel)", "\u30df\u30e9\u30fc\u30b9\u30bf\u30f3\u30b9\u3067\u653b\u6483\u3092\u8df3\u306d\u8fd4\u3059\u53cd\u5c04\u578b", KitRole.SENTINEL, "\u541b\u306f\u300c\u93e1\u300d\u3060\u3002\u5203\u3092\u8df3\u306d\u8fd4\u3057\u3001\u6575\u306e\u529b\u3092\u5df1\u306e\u7ce7\u3068\u305b\u3088\u3002", "\u53cd\u5c04\u306e\u58c1\u3067\u9060\u8ddd\u96e2\u30ad\u30c3\u30c8\u3092\u7121\u529b\u5316\u3057\u308d\u3002\u653b\u6483\u3092\u53d7\u3051\u6b62\u3081\u3066\u8df3\u306d\u8fd4\u3059\u3001\u6575\u306e\u529b\u306f\u5df1\u306e\u7ce7\u3060"),
    GLACIES("\u30b0\u30e9\u30ad\u30a8\u30b9", "\u00a7b\u2744 \u30b0\u30e9\u30ad\u30a8\u30b9 \u00a77(Controller)", "\u30d5\u30ed\u30b9\u30c8\u30b9\u30c8\u30e9\u30a4\u30af\u3067\u6575\u3092\u51cd\u7d50\u3055\u305b\u308b\u6c37\u7d50\u578b", KitRole.CONTROLLER, "\u541b\u306f\u300c\u6c37\u96ea\u300d\u3060\u3002\u5203\u306e\u51cd\u6c17\u3067\u3001\u5168\u3066\u3092\u51cd\u3066\u3064\u304b\u305b\u3088\u3002", "\u51b7\u6c17\u3067\u6575\u306e\u8db3\u3092\u6b62\u3081\u308d\u3002\u51cd\u7d50\u3057\u305f\u7372\u7269\u306f\u9003\u3052\u3089\u308c\u306a\u3044\u3002\u78ba\u5b9f\u306b\u4ed5\u7559\u3081\u308d"),
    SUPERIOR_MISTRAL("\u30b9\u30fc\u30da\u30ea\u30a2\u30fb\u30df\u30b9\u30c8\u30e9\u30eb", "\u00a76\u2605 \u30b9\u30fc\u30da\u30ea\u30a2\u30fb\u30df\u30b9\u30c8\u30e9\u30eb \u00a77(Initiator)", "\u7ba1\u7406\u8005\u5c02\u7528\u306e\u7a76\u6975\u98a8\u4f7f\u3044\u3002\u5168\u3066\u306e\u98a8\u3092\u7d71\u3079\u3001\u6575\u3092\u5dfb\u304d\u5c3d\u304f\u3059", KitRole.INITIATOR, "\u541b\u306f\u300c\u7a76\u6975\u306e\u66b4\u98a8\u300d\u3060\u3002\u3059\u3079\u3066\u306e\u98a8\u3092\u7d71\u3079\u3001\u6575\u3092\u5439\u304d\u5c3d\u304f\u305b\u3002", "\u5168\u3066\u3092\u8d85\u8d8a\u3057\u305f\u7ffc\u3067\u6226\u5834\u3092\u5236\u5727\u305b\u3088\u3002\u5168\u3066\u306e\u98a8\u3092\u7d71\u3079\u308b\u8005\u306b\u3001\u6575\u306f\u7acb\u3061\u3059\u3089\u8a31\u3055\u308c\u306a\u3044");

    private final String name;
    private final String displayName;
    private final String description;
    private final String lore;
    private final String playstyle;
    private final KitRole role;

    private KitType(String name, String displayName, String description, KitRole role, String lore, String playstyle) {
        this.name = name;
        this.displayName = displayName;
        this.description = description;
        this.role = role;
        this.lore = lore;
        this.playstyle = playstyle;
    }

    public String getName() {
        return this.name;
    }

    public String getDisplayName() {
        return this.displayName;
    }

    public String getDescription() {
        return this.description;
    }

    public String getLore() {
        return this.lore;
    }

    public String getPlaystyle() {
        return this.playstyle;
    }

    public KitRole getRole() {
        return this.role;
    }
}

